# Count the empty regions
empty_components = []
visited = [[False]*20 for _ in range(20)]

for r in range(20):
    for c in range(20):
        if grid[r][c] == 0 and not visited[r][c]:
            # BFS to find component
            component = []
            stack = [(r,c)]
            visited[r][c] = True
            while stack:
                cr, cc = stack.pop()
                component.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < 20 and 0 <= nc < 20 and grid[nr][nc] == 0 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
            if len(component) > 1:  # Only multi-cell regions
                empty_components.append(component)

print(f"Number of empty regions (multi-cell): {len(empty_components)}")
for i, comp in enumerate(empty_components):
    print(f"Region {i}: {len(comp)} cells")

